def P24(lang, crumbs, T):
    T = dict(T); X = EX24[lang]
    T['br_t'] = T['br_t'] + X['t']; T['br_f'] = T['br_f'] + X['f']; T['faq'] = T['faq'][:1] + X['faq'] + T['faq'][1:]
    return {
     "lang": lang, "url": ALT_24[lang], "alt": ALT_24,
     "title": T['title'], "desc": T['desc'], "ogtitle": T['ogtitle'], "ogdesc": T['ogdesc'],
     "crumbs": crumbs + [(T['crumb'], None)], "eyebrow": T['eyebrow'], "h1": T['h1'], "lead": T['lead'],
     "cta1": T['cta1'], "cta2": T['cta2'],
     "sezioni": [
      {"id": "in-brief", "tipo": "breve", "eyebrow": T['br_e'], "h2": T['br_h2'], "testo": T['br_t'], "fatti": T['br_f']},
      {"id": "how", "tipo": "passi", "eyebrow": T['how_e'], "h2": T['how_h2'], "corpo": T['how']},
      {"id": "included", "tipo": "cards", "eyebrow": T['inc_e'], "h2": T['inc_h2'], "corpo": T['inc']},
      {"id": "who", "tipo": "testo", "eyebrow": T['who_e'], "h2": T['who_h2'], "corpo": T['who']},
      {"id": "video", "tipo": "video", "eyebrow": T['vid_e'], "h2": T['vid_h2'], "video": ['reel-sito-con-ai-in-1-minuto', 'reel-sfida-sito-dentista', 'reel-quanto-costa-un-sito', 'reel-risposta-in-24-ore', 'reel-sito-lento', 'reel-micro-animazioni-sito']}],
     "faqtitle": T['faqtitle'], "faq": T['faq'], "ctabox": T['cta'], "altrititle": T['altrititle'], "altri": T['altri'],
     "svc": svc(T['svc_name'], T['svc_type'], T['svc_desc'], T['svc_cat'], area=EU,
                offer={"price": "350.00", "desc": T['offer']})}

def PVID(lang, crumbs, T):
    return {
     "lang": lang, "url": ALT_VID[lang], "alt": ALT_VID, "ogimg": "/assets/video/spot-ai-roadster.jpg",
     "title": T['title'], "desc": T['desc'], "ogtitle": T['ogtitle'], "ogdesc": T['ogdesc'],
     "crumbs": crumbs + [(T['crumb'], None)], "eyebrow": T['eyebrow'], "h1": T['h1'], "lead": T['lead'],
     "cta1": T['cta1'], "cta2": T['cta2'],
     "sezioni": [
      {"id": "work", "tipo": "video", "eyebrow": "Portfolio", "h2": T['pf_h2'], "lead": T['pf_lead'], "video": TUTTI},
      {"id": "in-brief", "tipo": "breve", "eyebrow": T['br_e'], "h2": T['br_h2'], "testo": T['br_t'], "fatti": T['br_f']},
      {"id": "types", "tipo": "cards", "eyebrow": T['typ_e'], "h2": T['typ_h2'], "corpo": T['typ']},
      {"id": "how", "tipo": "passi", "eyebrow": T['how_e'], "h2": T['how_h2'], "corpo": T['how']}],
     "faqtitle": T['faqtitle'], "faq": T['faq'], "ctabox": T['cta'], "altrititle": T['altrititle'], "altri": T['altri'],
     "svc": svc(T['svc_name'], T['svc_type'], T['svc_desc'], T['svc_cat'], area=EU)}

def PAPP(lang, crumbs, T):
    sez = [{"id": "in-brief", "tipo": "breve", "eyebrow": T['br_e'], "h2": T['br_h2'], "testo": T['br_t'], "fatti": T['br_f']},
           {"id": "sectors", "tipo": "cards", "eyebrow": T['sec_e'], "h2": T['sec_h2'], "corpo": T['sec']}]
    if T.get('links'):
        sez.append({"id": "pages", "tipo": "link", "eyebrow": T['lnk_e'], "h2": T['lnk_h2'], "gruppi": [("", T['links'])]})
    sez += [{"id": "how", "tipo": "passi", "eyebrow": T['how_e'], "h2": T['how_h2'], "corpo": T['how']},
            {"id": "why", "tipo": "cards", "eyebrow": T['why_e'], "h2": T['why_h2'], "corpo": T['why']}]
    return {
     "lang": lang, "url": ALT_APP[lang], "alt": ALT_APP,
     "title": T['title'], "desc": T['desc'], "ogtitle": T['ogtitle'], "ogdesc": T['ogdesc'],
     "crumbs": crumbs + [(T['crumb'], None)], "eyebrow": T['eyebrow'], "h1": T['h1'], "lead": T['lead'],
     "cta1": T['cta1'], "cta2": T['cta2'], "sezioni": sez,
     "faqtitle": T['faqtitle'], "faq": T['faq'], "ctabox": T['cta'], "altrititle": T['altrititle'], "altri": T['altri'],
     "svc": svc(T['svc_name'], T['svc_type'], T['svc_desc'], T['svc_cat'], area=EU,
                offer={"price": "750.00", "desc": T['offer']})}

